        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 3rem);
        overflow: hidden;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.35rem 0.75rem;
        border-radius: 999px;
        background: rgba(79, 124, 255, 0.12);
        color: var(--accent-strong);
        font-weight: 700;
        font-size: 0.875rem;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 1rem 0 0.75rem;
