        padding: 0 0 3rem;
      }

      .faq-grid {
        display: grid;
        gap: 1rem;
        margin-top: 1.5rem;
      }

      .example {
        border: 1px solid var(--border);
        background: var(--panel);
        border-radius: 1.35rem;
        box-shadow: 0 8px 24px rgba(21, 32, 51, 0.06);
        overflow: hidden;
      }

      .question {
        appearance: none;
        width: 100%;
        border: 0;
        background: transparent;
        color: inherit;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.2rem 1.25rem;
        cursor: pointer;
        text-align: left;
        font: inherit;
        font-weight: 700;
      }

      .question:hover {
        background: #f6f9ff;
      }

      .question:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: -3px;
