          outline-color: Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <div id="app"></div>

    <script>
      const faqData = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats purr for a few reasons: comfort, bonding, self-soothing, and sometimes when they are feeling uneasy. The sound often signals that a cat is relaxed, but context matters.",
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day. Kittens and older cats usually rest even more, which is why a cat napping in a sunbeam is such a common sight.",
        },
        {
          question: "What should I feed my cat?",
          answer:
            "Cats need a complete diet made for felines, with plenty of animal protein and the right balance of nutrients. Fresh water should always be available, and treats should stay limited.",
        },
        {
          question: "Do indoor cats need exercise?",
          answer:
            "Yes. Indoor cats benefit from daily play, climbing, chasing toys, and puzzle feeders. Regular activity helps with weight control, boredom, and overall health.",
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is often a comfort behavior that starts in kittenhood. Adult cats may knead when they feel calm, secure, or especially affectionate.",
        },
        {
          question: "How can I tell if a cat is happy?",
          answer:
            "Relaxed ears, a soft gaze, normal grooming, playful behavior, and a tail held comfortably are all good signs. Every cat is different, so watch for changes in their usual routine.",
        },
      ];

      function createFaqItem(item, index) {
        const detailsId = `faq-answer-${index}`;
        const buttonId = `faq-question-${index}`;

        return `
          <div class="example">
            <button
              class="question"
              id="${buttonId}"
              type="button"
              aria-expanded="false"
              aria-controls="${detailsId}"
            >
              <span>${item.question}</span>
              <svg class="chevron" viewBox="0 0 20 20" aria-hidden="true" focusable="false">
                <path d="M5.5 7.5L10 12l4.5-4.5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>
              </svg>
            </button>
            <div class="details" id="${detailsId}" role="region" aria-labelledby="${buttonId}" hidden>
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function App() {
        return `
          <div class="shell">
            <header>
              <div class="hero">
                <span class="eyebrow">Cat FAQ</span>
                <h1>Answers for curious cat people</h1>
                <p class="intro">
                  A simple FAQ with expandable answers, built for quick scanning and easy keyboard navigation.
                </p>
              </div>
            </header>
            <main id="main">
              <section aria-labelledby="faq-title">
                <h2 id="faq-title" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden;">Frequently asked questions</h2>
                <div class="faq-grid">
                  ${faqData.map(createFaqItem).join("")}
                </div>
              </section>
            </main>
          </div>
        `;
      }

      document.getElementById("app").innerHTML = App();

      document.querySelectorAll(".question").forEach((button) => {
        button.addEventListener("click", () => {
          const expanded = button.getAttribute("aria-expanded") === "true";
          const details = document.getElementById(button.getAttribute("aria-controls"));

          button.setAttribute("aria-expanded", String(!expanded));
          details.hidden = expanded;
        });
      });
    </script>
